result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formula.py", "content": """"Empirical and molecular formula finder from mass percentages."""

WEIGHTS = {
    "C": 12.011,
    "H": 1.008,
    "O": 15.999,
    "P": 30.974,
    "N": 14.007,
}


def _sub(n: int) -> str:
    """Format a stoichiometric coefficient (omit when 1)."""
    return str(n) if n != 1 else ""


def _parse_formula(formula: str):
    """Parse a simple formula like 'C6H12O6' into {element: count}."""
    import re

    result = {}
    for elem, num in re.findall(r"([A-Z][a-z]?)(\d*)", formula):
        if not elem:
            continue
        result[elem] = result.get(elem, 0) + (int(num) if num else 1)
    return result


def _format_formula(counts: dict, order) -> str:
    parts = []
    for elem in order:
        n = counts[elem]
        if n > 0:
            parts.append(f"{elem}{_sub(n)}")
    return "".join(parts)


def formula_from_percent(percents: dict, molar_mass: float | None = None) -> str:
    """Convert mass percentages to empirical (or molecular) formula.

    percents: mapping element -> mass percent
    molar_mass: optional molar mass of the molecular compound; when given,
        the empirical formula is scaled up to the molecular formula.
    """
    total = sum(percents.values())
    if abs(total - 100.0) > 0.5:
        raise ValueError(
            f"Percentages must sum to 100 (within 0.5); got {total:.2f}"
        )

    # Convert to moles
    moles = {elem: pct / WEIGHTS[elem] for elem, pct in percents.items()}

    # Divide by the smallest
    smallest = min(moles.values())
    ratios = {elem: n / smallest for elem, n in moles.items()}

    # Find smallest integer k <= 6 making every ratio within 0.05 of k*ratio
    k = None
    for cand in range(1, 7):
        if all(abs(cand * r - round(cand * r)) <= 0.05 for r in ratios.values()):
            k = cand
            break
    if k is None:
        raise ValueError("Could not find integer ratios within tolerance")

    counts = {elem: int(round(k * r)) for elem, r in ratios.items()}
    order = list(percents.keys())
    empirical = _format_formula(counts, order)

    if molar_mass is None:
        return empirical

    # Scale to molecular formula
    emp_mass = sum(WEIGHTS[e] * n for e, n in counts.items())
    scale = round(molar_mass / emp_mass)
    if scale < 1:
        raise ValueError("Molar mass smaller than empirical formula mass")
    mol_counts = {e: n * scale for e, n in counts.items()}
    return _format_formula(mol_counts, order)
