from formula import formula_from_percent


def test_glucose_empirical():
    assert (
        formula_from_percent({"C": 40.00, "H": 6.71, "O": 53.29}, None)
        == "CH2O"
    )


def test_glucose_molecular():
    assert (
        formula_from_percent({"C": 40.00, "H": 6.71, "O": 53.29}, 180.16)
        == "C6H12O6"
    )


def test_p2o5():
    # raw ratio P : O is 1 : 2.5 -> k = 2
    assert formula_from_percent({"P": 43.64, "O": 56.36}) == "P2O5"


@pytest.mark.parametrize(
    "bad",
    [
        {"C": 40.0, "H": 6.71},          # sums to 46.71
        {"C": 50.0, "H": 60.0},          # sums to 110
        {"N": 95.0},                     # single element, wrong total
    ],
)
def test_bad_total_raises(bad):
    with pytest.raises(ValueError):
        formula_from_percent(bad)


def test_tolerance_allows_small_deviation():
    # 99.7 total is within 0.5 of 100 -> no error
    assert formula_from_percent({"C": 40.0, "H": 6.71, "O": 53.0}) == "CH2O"
